// ── Abstract base class ──────────────────────────────────────────────
class ReportGenerator {
  // TEMPLATE METHOD — defines the fixed skeleton
  // Convention: do not override this in subclasses
  generate(data) {
    const raw       = this.fetchData(data);       // default step
    const formatted = this.formatData(raw);       // abstract step
    this.beforeWrite();                           // hook
    const result    = this.writeOutput(formatted); // abstract step
    this.afterWrite();                            // hook
    return result;
  }

  // Default step — subclasses may override
  fetchData(data) {
    return data;  // default: pass data through unchanged
  }

  // Abstract steps — MUST be overridden (runtime guard)
  formatData(raw) {
    throw new Error(`${this.constructor.name} must implement formatData()`);
  }
  writeOutput(content) {
    throw new Error(`${this.constructor.name} must implement writeOutput()`);
  }

  // Hooks — optional, empty by default
  beforeWrite() {}
  afterWrite()  {}
}

// ── Concrete: CSV ────────────────────────────────────────────────────
class CsvReport extends ReportGenerator {
  formatData(rows) {
    if (!rows.length) return '';
    const header = Object.keys(rows[0]).join(',');
    const body   = rows.map(r =>
      Object.values(r).map(v => `"${v}"`).join(',')
    ).join('\n');
    return `${header}\n${body}`;
  }

  writeOutput(content) {
    console.log('[CSV] Writing report.csv');
    // In real code: fs.writeFileSync('report.csv', content);
    return { file: 'report.csv', bytes: content.length };
  }
  // beforeWrite / afterWrite — not needed, inherited no-ops
}

// ── Concrete: HTML ───────────────────────────────────────────────────
class HtmlReport extends ReportGenerator {
  // Override fetchData — HTML reports need enriched data
  fetchData(data) {
    return data.map(row => ({ ...row, _html: true }));
  }

  formatData(rows) {
    const cols = Object.keys(rows[0]).filter(k => k !== '_html');
    const ths  = cols.map(k => `<th>${k}</th>`).join('');
    const trs  = rows.map(r =>
      `<tr>${cols.map(k => `<td>${r[k]}</td>`).join('')}</tr>`
    ).join('\n');
    return `<table><thead><tr>${ths}</tr></thead><tbody>\n${trs}\n</tbody></table>`;
  }

  // Override hook — inject HTML-specific pre-write validation
  beforeWrite() {
    console.log('[HTML] Validating markup before write...');
  }

  writeOutput(content) {
    console.log('[HTML] Writing report.html');
    return { file: 'report.html', bytes: content.length };
  }
}

// ── Concrete: PDF (with afterWrite hook) ─────────────────────────────
class PdfReport extends ReportGenerator {
  formatData(rows) {
    // Simplified: real PDF would use pdfkit or similar
    return rows.map(r => Object.values(r).join(' | ')).join('\n');
  }

  writeOutput(content) {
    console.log('[PDF] Writing report.pdf via PDFLib...');
    return { file: 'report.pdf', bytes: content.length };
  }

  afterWrite() {
    console.log('[PDF] Uploading to S3 archive bucket...');
  }
}

// ── Usage ─────────────────────────────────────────────────────────────
const dataset = [
  { name: 'Alice', sales: 120, region: 'APAC' },
  { name: 'Bob',   sales: 98,  region: 'EMEA' },
  { name: 'Carol', sales: 210, region: 'AMER' },
];

[new CsvReport(), new HtmlReport(), new PdfReport()].forEach(r => {
  const result = r.generate(dataset);
  console.log('Generated:', result);
});
// Each report runs the same skeleton; only the step implementations differ

sections.content:
Choosing between a hook and an abstract step is a design decision that shapes how easy your pattern is to use correctly.

**Abstract steps** impose a hard contract. Every subclass must implement them, or the runtime throws. Use abstract steps for operations that are genuinely meaningless without a concrete implementation — you have no sensible default. `formatData()` is abstract because there is no generic 'format data' operation; it always depends on the output format.

**Hooks** are opt-in. They have empty defaults. A subclass that doesn't need to inject behaviour at a hook point simply ignores it. Use hooks for:
- **Pre/post logic** that only some subclasses need (`beforeWrite`, `afterSave`)
- **Notification points** where subclasses may want to track or log something
- **Conditional extra steps** — e.g., some reports may need to compress output before writing, others do not

A common design mistake is making *everything* abstract. This forces every subclass to implement no-op methods, creating noise and friction:

```js
// BAD: forced no-op on every subclass
class CsvReport extends ReportGenerator {
  beforeWrite() { /* nothing to do, but forced to implement */ }
  afterWrite()  { /* nothing to do, but forced to implement */ }
  formatData(raw) { /* real work here */ }
  writeOutput(content) { /* real work here */ }
}
```

Versus:
```js
// GOOD: hook with no-op default — subclass ignores what it doesn't need
class CsvReport extends ReportGenerator {
  // beforeWrite / afterWrite — inherited no-ops, no boilerplate
  formatData(raw) { /* real work here */ }
  writeOutput(content) { /* real work here */ }
}
```

Rule of thumb: **abstract = required; hook = optional.** Default implementations should be the most common behaviour, not a no-op — reserve no-op defaults for hooks.

